// Phase 2: Eingang prüfen und bereinigen, bevor etwas an das LLM oder die Datenbank geht.
// Schützt das Kontextfenster (4.096 Tokens): System-Prompt ca. 900 + Mail bis ca. 1.900 + Antwort bis 1.024 Tokens
const MAX_ZEICHEN = 6000;
const eingang = $json.body ?? {};
const fehler = [];

for (const feld of ['message_id', 'from', 'subject', 'body']) {
  if (typeof eingang[feld] !== 'string' || eingang[feld].trim() === '') {
    fehler.push(`Feld "${feld}" fehlt oder ist leer`);
  }
}
if (fehler.length) {
  return { json: { gueltig: false, fehler } };
}

// HTML-Mails in Text umwandeln, Leerraum vereinheitlichen
const bereinigen = (s) => s
  .replace(/<(style|script)[\s\S]*?<\/\1>/gi, ' ')
  .replace(/<br\s*\/?>|<\/p>/gi, '\n')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ')
  .replace(/\r\n/g, '\n')
  .replace(/[ \t]+/g, ' ')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

const text = bereinigen(eingang.body);
return {
  json: {
    gueltig: true,
    mail: {
      mail_id: eingang.message_id.trim(),
      absender: eingang.from.trim(),
      betreff: bereinigen(eingang.subject).slice(0, 300),
      text: text.slice(0, MAX_ZEICHEN),
      gekuerzt: text.length > MAX_ZEICHEN,
      empfangen_am: eingang.received_at ?? null,
    },
  },
};

